add_filter( 'woocommerce_grouped_price_html', 'perfectpixel_grouped_price_html', 10, 3 );

function perfectpixel_grouped_price_html( $html, $product, $child_prices ) {
	if ( 'hide' === '{{grouped_price_mode}}' ) {
		return '';
	}
	$child_prices = array_filter( (array) $child_prices, 'is_numeric' );
	if ( count( array_unique( $child_prices ) ) < 2 ) {
		return $html; // No range to replace.
	}
	return esc_html( '{{grouped_price_prefix}}' ) . ' ' . wc_price( min( $child_prices ) ) . $product->get_price_suffix();
}
